//! FORM relList uses actual attributes with named-control-aware forwarding.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=output rel='first second first' class=stable><input id=first name=q value=Seed><input id=second value=second></form><label id=label>Label</label><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://form-rel-list.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn form_rel_list_canonical_same_object_exact_live_tokens(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('output'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'relList');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get relList'||a.set.name!=='set relList'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'relList'))throw 'canonical';var t=x.relList;if(t!==a.get.call(x)||t!==x.relList||t===x.classList||!(t instanceof DOMTokenList)||t.value!=='first second first'||t.length!==2||Array.from(t).join(',')!=='first,second')throw 'actual tokens';t.add('A\ud800Z');if(x.rel!==t.value||!t.contains('A\ud800Z')||t.supports('noopener')||t.supports('noreferrer')||t.supports('opener'))throw 'truthful live exact tokens';"#);}
#[test]
fn form_rel_list_named_control_masks_ordinary_forward_target(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('output'),n=document.getElementById('first'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'relList'),t=a.get.call(x);n.setAttribute('name','relList');if(x.relList!==n)throw 'named mask';var calls=0;a.set.call(x,{toString:function(){calls++;return 'forwarded';}});if(calls!==1||n.value!=='forwarded'||t.value!=='first second first'||x.relList!==n)throw 'ordinary named target';n.setAttribute('name','q');x.relList='native';if(x.relList!==t||t.value!=='native')throw 'unmask';");}
#[test]
fn form_rel_list_inert_exact_namespace_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml','form');x.setAttributeNS('urn:other','rel','foreign');x.setAttributeNS(null,'REL','upper');var t=x.relList;if(t.value!==''||t.length)throw 'exact source';x.relList='A\ud800Z B';var copy=x.cloneNode(false),other=copy.relList;other.remove('B');if(x.relList!==t||copy.relList!==other||other===t||t.value!=='A\ud800Z B'||other.value!=='A\ud800Z'||x.getAttributeNS('urn:other','rel')!=='foreign')throw 'independent';"#);}

#[test]
fn form_rel_list_exact_tokens_mutate_for_without_class_or_label_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),tokens=output.relList,classes=output.classList;output.setAttribute('rel','A\ud800z A�z A\ud800z');if(tokens.length!==2||tokens[0]!=='A\ud800z'||!tokens.contains('A\ud800z')||!tokens.contains('A�z'))throw 'exact source token units';tokens.remove('A�z');tokens.add('B\udfffz','B\udfffz');if(tokens.value!=='A\ud800z B\udfffz'||!tokens.replace('A\ud800z','C\ud800z')||tokens.value!=='C\ud800z B\udfffz')throw 'exact token serialization';if(tokens.toggle('B\udfffz')||!tokens.toggle('D\ud800z',true)||tokens.value!=='C\ud800z D\ud800z')throw 'exact toggle';if(output.getAttribute('rel')!==tokens.value||output.relList!==tokens||output.classList!==classes||classes.value!=='stable')throw 'independent native attributes and label authority';"#);}
#[test]
fn form_rel_list_live_iteration_observation_and_validation_keep_actual_for_record(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),t=output.relList,a=output.getAttributeNode('rel'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});t.toggle('first',true);t.replace('missing','last');if(watch.takeRecords().length||t.value!=='first second first')throw 'no-op preserves spelling and observation';t.value='A\ud800z A�z';t.remove('A�z');var records=watch.takeRecords();if(records.length!==2||records[0].oldValue!=='first second first'||records[1].oldValue!=='A\ud800z A�z'||records[1].attributeName!=='rel'||records[1].attributeNamespace!==null||a!==output.getAttributeNode('rel')||a.value!==t.value)throw 'actual record observations';t.value='one two';var iterator=t.values();if(iterator.next().value!=='one')throw 'iterator first';t.add('three');if(iterator.next().value!=='two'||iterator.next().value!=='three'||!iterator.next().done)throw 'live native iterator';var seen=[];t.forEach(function(v,i,list){if(list!==t)throw 'callback list';seen.push(v);if(i===0)t.remove('two');});if(seen.join(',')!=='one,three')throw 'live callback';var calls='';try{t.add('',{toString:function(){calls+='convert';output.setAttribute('rel','callback');return 'late';}});throw 'missing validation';}catch(e){if(e.name!=='SyntaxError')throw e;}if(calls!=='convert'||t.value!=='callback')throw 'conversion before validation';var marker={};try{t.value={toString:function(){output.setAttribute('rel','effect');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(t.value!=='effect')throw 'completed author effects';"#);}
#[test]
fn form_rel_list_native_and_inert_refusals_preserve_records_and_recover(){for inert in [false,true]{for expression in [r#"list.value='long A\ud800z B\udfffz';"#,r#"list.add('longA\ud800z');"#,r#"output.relList='long A\ud800z B\udfffz';"#]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('form');output.relList='seed';var list=output.relList,attr=output.getAttributeNode('rel'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"}else{"var output=document.getElementById('output'),list=output.relList;list.value='seed';var attr=output.getAttributeNode('rel'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"});p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=0,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(list.value!=='seed'||attr.value!=='seed'||watch.takeRecords().length)throw 'atomic refused token write';list.value='fresh';if(output.relList!==list||attr!==output.getAttributeNode('rel')||attr.value!=='fresh'||watch.takeRecords().length!==1)throw 'fresh exact token recovery';");}}}}
#[test]
fn form_rel_list_getter_and_paid_reads_keep_identity_and_recover(){for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('form');output.relList='A\\ud800z B\\udfffz';var list=output.relList;"}else{"var output=document.getElementById('output');output.relList='A\\ud800z B\\udfffz';var list=output.relList;"});let Value::Host(owner)=p.runtime.execute("output;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!()};let retained=p.state.retained;let commits=p.state.dom_commits;let limit=p.state.retained_limit;p.state.retained_limit=retained;let Value::Host(list)=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.form_rel_list_get(owner).unwrap()else{panic!()};assert_eq!((p.state.retained,p.state.dom_commits),(retained,commits));for mode in 0..4{p.begin_job();p.state.retained_limit=limit;match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.class_list_get(list,"0").unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit"),"{e}");assert_eq!((p.state.retained,p.state.dom_commits),(retained,commits));}p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(output.relList!==list||list[0]!=='A\\ud800z'||list[1]!=='B\\udfffz')throw 'fresh paid token read recovery';");}}

#[test]
fn form_rel_list_native_inert_namespace_and_supported_processing_truth(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=new Document(),output=owner.createElementNS('http://www.w3.org/1999/xhtml','t:form');output.rel='native';"}else{"var output=document.getElementById('output');output.rel='native';"});run(&mut d,&mut f,&mut p,r#"var list=output.relList,attr=output.getAttributeNode('rel'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});output.setAttributeNS('urn:foreign','rel','foreign');output.setAttributeNS(null,'REL','upper');watch.takeRecords();if(list!==output.relList||list.value!=='native'||list.length!==1||list[0]!=='native')throw 'exact null namespace source';var calls=0;if(list.supports({toString:function(){calls++;return 'NOOPENER';}})||calls!==1||list.supports('noreferrer')||list.supports('opener')||list.supports('')||list.supports('unknown'))throw 'processing tokens require actual implementation';var caught=false;try{list.supports(Symbol('token'));}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||list.value!=='native'||attr!==output.getAttributeNode('rel'))throw 'supported lookup preserves source';list.add('A\ud800Z');if(attr.value!=='native A\ud800Z'||output.rel!==list.value||watch.takeRecords().length!==1||list===output.classList)throw 'separate exact live relation tokens';"#);}
}

#[test]
fn form_rel_list_inert_copy_adoption_import_refusal_and_typed_handle_guards(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('form');source.relList='A\ud800z A�z';var list=source.relList,copy=source.cloneNode(true),copied=copy.relList,attr=copy.getAttributeNode('rel'),target=document.implementation.createHTMLDocument('target');target.adoptNode(copy);target.body.appendChild(copy);copied.remove('A�z');copied.add('B\udfffz');if(String(copied)!=='A\ud800z B\udfffz'||copied.item(1)!=='B\udfffz'||Array.from(copied).join(',')!=='A\ud800z,B\udfffz'||copy.relList!==copied||list===copied||copied.value!=='A\ud800z B\udfffz'||list.value!=='A\ud800z A�z'||attr.value!==copied.value||attr.ownerDocument!==target||copy.ownerDocument!==target||source.classList.value!=='')throw 'inert exact clone adoption';"#);let before=format!("{:?}",d.nodes);let error=p.runtime.execute("document.importNode(copy,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Import supports ordinary HTML containers and inert data nodes."),"{error}");assert_eq!(format!("{:?}",d.nodes),before);p.state.node_limit=d.nodes.len();p.begin_job();run(&mut d,&mut f,&mut p,r#"var isolated=owner.createElement('form'),held=isolated.relList;held.value='X\ud800z';held.add('Y\udfffz');if(isolated.relList!==held||held.length!==2||held.value!=='X\ud800z Y\udfffz')throw 'inert source without main slots';var div=owner.createElement('div');"#);
for expression in ["div;","document.getElementById('label');"]{let Value::Host(owner)=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!()};let forged=script_class_list::area_rel_handle(owner);let before=(p.state.retained,p.state.dom_commits);let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert!(!bridge.class_list_receiver(forged));assert!(bridge.class_list_get(forged,"length").is_err());assert!(bridge.class_list_set(forged,"value",Value::String("bad".into())).is_err());assert_eq!((bridge.state.retained,bridge.state.dom_commits),before);}
}
#[test]
fn form_rel_list_prototype_authority_original_forward_value_and_false_set(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"'use strict';var x=document.getElementById('output'),P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'relList'),t=a.get.call(x),order='',seen,receiver,target={set value(v){order+='set';seen=v;receiver=this;}},value={toString:function(){order+='convert';return 'bad';}};Object.defineProperty(P,'relList',{get:function(){order+='get';return target;},configurable:true});a.set.call(x,value);if(order!=='getset'||seen!==value||receiver!==target||t.value!=='first second first')throw 'ordinary forward';var symbol=Symbol();a.set.call(x,symbol);if(seen!==symbol)throw 'symbol unchanged';Object.defineProperty(target,'value',{value:'fixed',writable:false,configurable:true});a.set.call(x,value);if(target.value!=='fixed')throw 'false set';target=new Proxy({}, {set:function(){return false;}});a.set.call(x,value);target=3;try{a.set.call(x,value);throw 'primitive';}catch(e){if(!(e instanceof TypeError))throw e;}if(order.indexOf('convert')!==-1)throw 'premature conversion';Object.defineProperty(P,'relList',a);x.relList='recovered';if(x.relList!==t||t.value!=='recovered')throw 'restore';"#);}
#[test]
fn form_rel_list_saved_child_origin_precedes_author_get_and_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('output'),P=HTMLFormElement.prototype,original=Object.getOwnPropertyDescriptor(P,'relList'),list=x.relList,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFormElement.prototype,'relList'),calls=0;Object.defineProperty(P,'relList',{get:function(){calls++;return list;},configurable:true});a.set.call(x,'first');if(calls!==1)throw 'same origin';calls=0;");let before=format!("{:?}",d.nodes);p.set_location(&crate::navigation::address("https://foreign-form-rel-list.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let e=p.runtime.execute("a.set.call(x,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);p.set_location(&crate::navigation::address("https://form-rel-list.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin ordering';a.set.call(x,'fresh');if(calls!==1||list.value!=='fresh')throw 'recovery';Object.defineProperty(P,'relList',original);");}
